// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 newMin, uint256 initChain, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        newMin = bound(newMin, 0, type(uint256).max);

        vm.prank(actor);
        c.SetMinSum(newMin);

        vm.prank(actor);
        c.Initialized();

        uint256 actualMin = c.MinSum();
        assertTrue(actualMin == newMin, "MinSum must equal the last SetMinSum argument after initialization");
    }
}
